import AppKit
import Foundation

@MainActor
public enum ClipboardReader {
    /// Markers from nspasteboard.org that apps set on secrets and short-lived or generated items.
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType", "com.agilebits.onepassword", "net.antelle.keeweb",
        "Pasteboard generator type",
    ]
    /// Keep in step with the password managers that Capture turns completions off for.
    static let passwordManagers: Set<String> = [
        "com.1password.1password", "com.agilebits.onepassword", "com.agilebits.onepassword7",
        "com.agilebits.onepassword-osx", "com.apple.Passwords", "com.apple.keychainaccess",
        "com.lastpass.lastpassmacdesktop", "com.lastpass.LastPass", "com.dashlane.dashlanephonefinal",
        "com.dashlane.Dashlane", "com.bitwarden.desktop", "com.callpod.keepermac.lite",
        "com.keepersecurity.passwordmanager", "com.sibersystems.RoboFormMac", "com.roboform.mac", "com.nordsec.nordpass",
        "in.sinew.Enpass-Desktop", "com.ascendo.DataVaultMac", "me.proton.pass.electron", "com.mseven.msecuremac",
        "com.symantec.NortonPasswordManager.combined", "org.keepassx.keepassx", "org.keepassxc.keepassxc",
        "net.antelle.keeweb", "com.markmcguill.strongbox.mac", "com.selznick.PasswordWallet",
        "com.outercorner.Secrets", "com.outercorner.Secrets-setapp", "com.outercorner.osx.Secrets",
        "com.outercorner.Secrets-safari",
    ]

    private static var lastChangeCount: Int?
    private static var lastChangeDate: Date?
    private static var lastChangeFromPasswordManager = false
    private static var appsSincePoll: Set<String> = []
    private static var activationObserver: (any NSObjectProtocol)?
    private static var monitor: Task<Void, Never>?

    /// True when the user set Ghostwriter to always paste from other apps in System Settings. Until then
    /// clipboard text stays unread, so suggestions never trigger the system's paste alert.
    public static var accessAllowed: Bool {
        NSPasteboard.general.accessBehavior == .alwaysAllow
    }

    /// Reads the clipboard once so macOS shows its paste alert and lists Ghostwriter in System Settings,
    /// where the user can choose to always allow it. The text read here is discarded.
    public static func requestAccess() {
        _ = NSPasteboard.general.string(forType: .string)
    }

    public static func startMonitoring() {
        guard monitor == nil else { return }
        lastChangeCount = NSPasteboard.general.changeCount
        appsSincePoll = frontmostBundleID().map { [$0] } ?? []
        activationObserver = NSWorkspace.shared.notificationCenter.addObserver(
            forName: NSWorkspace.didActivateApplicationNotification, object: nil, queue: .main
        ) { notification in
            let app = notification.userInfo?[NSWorkspace.applicationUserInfoKey] as? NSRunningApplication
            let bundleID = app?.bundleIdentifier
            MainActor.assumeIsolated {
                if let bundleID { appsSincePoll.insert(bundleID) }
            }
        }
        monitor = Task { @MainActor in
            while !Task.isCancelled {
                noteChange()
                do {
                    try await Task.sleep(for: .seconds(1))
                } catch {
                    return
                }
            }
        }
    }

    public static func recentText(maxAge: Double, maxCharacters: Int) -> String? {
        startMonitoring()
        noteChange()
        guard let changed = lastChangeDate, Date().timeIntervalSince(changed) <= maxAge,
              !lastChangeFromPasswordManager
        else { return nil }
        guard accessAllowed else { return nil }
        let pasteboard = NSPasteboard.general
        if (pasteboard.types ?? []).contains(where: { ignoredTypes.contains($0.rawValue) }) { return nil }
        guard let raw = pasteboard.string(forType: .string) else { return nil }
        let text = raw.trimmingCharacters(in: .whitespacesAndNewlines)
        guard isUsable(text) else { return nil }
        return String(text.prefix(maxCharacters))
    }

    private static func noteChange() {
        let count = NSPasteboard.general.changeCount
        let frontmost = frontmostBundleID()
        let sources = appsSincePoll.union(frontmost.map { [$0] } ?? [])
        appsSincePoll = frontmost.map { [$0] } ?? []
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        lastChangeDate = Date()
        lastChangeFromPasswordManager = !sources.isDisjoint(with: passwordManagers)
    }

    private static func frontmostBundleID() -> String? {
        NSWorkspace.shared.frontmostApplication?.bundleIdentifier
    }

    nonisolated static func isUsable(_ text: String) -> Bool {
        guard !text.isEmpty, !text.contains("PRIVATE KEY-----") else { return false }
        let tokens = text.split(whereSeparator: \.isWhitespace)
        guard tokens.count == 1 else {
            return !tokens.contains { looksSecret($0.trimmingCharacters(in: edgeCharacters)) }
        }
        guard isURL(text) || text.count >= 20 else { return false }
        return !looksSecret(text)
    }

    private nonisolated static let edgeCharacters = CharacterSet.punctuationCharacters.union(.symbols)
    private nonisolated static let wordPunctuation: Set<Character> = [
        ".", ",", ";", ":", "-", "_", "/", "'", "\u{2019}", "\"", "“", "”", "(", ")", "[", "]", "{", "}", "<", ">",
        "=", "@", "&",
    ]
    private nonisolated static let keyPrefixes = [
        "sk-", "sk_live_", "sk_test_", "rk_live_", "pk_live_", "ghp_", "gho_", "ghu_", "ghs_", "ghr_",
        "github_pat_", "glpat-", "xoxb-", "xoxp-", "xoxa-", "xoxe-", "xapp-", "AKIA", "ASIA", "AIza", "ya29.",
        "npm_", "pypi-", "hf_", "eyJ", "-----BEGIN",
    ]

    private nonisolated static func looksSecret(_ token: String) -> Bool {
        if keyPrefixes.contains(where: { token.hasPrefix($0) && token.count >= $0.count + 8 }) { return true }
        if isURL(token) {
            let authority = token.drop { $0 != "/" }.dropFirst(2).prefix { $0 != "/" }
            return authority.contains("@") || longestLetterDigitRun(token) >= 24
        }
        return (token.count >= 8 && characterClasses(token) >= 3) || longestLetterDigitRun(token) >= 16
    }

    private nonisolated static func isURL(_ token: some StringProtocol) -> Bool {
        token.hasPrefix("https://") || token.hasPrefix("http://")
    }

    private nonisolated static func characterClasses(_ token: String) -> Int {
        var lower = false, upper = false, digit = false, symbol = false
        for character in token {
            if character.isLowercase {
                lower = true
            } else if character.isUppercase {
                upper = true
            } else if character.isNumber {
                digit = true
            } else if !character.isLetter, !wordPunctuation.contains(character) {
                symbol = true
            }
        }
        return [lower, upper, digit, symbol].filter { $0 }.count
    }

    private nonisolated static func longestLetterDigitRun(_ token: String) -> Int {
        var longest = 0, length = 0, hasLetter = false, hasDigit = false
        for character in token + " " {
            if character.isASCII, character.isLetter || character.isNumber {
                length += 1
                if character.isLetter { hasLetter = true } else { hasDigit = true }
                continue
            }
            if hasLetter, hasDigit { longest = max(longest, length) }
            length = 0
            hasLetter = false
            hasDigit = false
        }
        return longest
    }
}
